function draw() {
    ctx.clearRect(0, 0, CONFIG.width, CONFIG.height);
    // rotating background (simple planet)
    ctx.save();
    ctx.translate(CONFIG.width / 2, CONFIG.height / 2);
    ctx.rotate(bgAngle);
    ctx.fillStyle = '#223';
    ctx.beginPath();
    ctx.arc(0, 0, 200, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    // draw orbs
    ctx.fillStyle = 'yellow';
    for (const o of orbs) {
      if (o.collected) continue;
      ctx.beginPath();
      ctx.arc(o.x, o.y, CONFIG.orb.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // draw asteroids
    ctx.fillStyle = 'gray';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, CONFIG.asteroid.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // draw ship
    if (ship.alive) {
      ctx.save();
      ctx.translate(ship.x, ship.y);
      ctx.rotate(ship.angle);
      ctx.fillStyle = 'white';
      ctx.beginPath();
      ctx.moveTo(10, 0);
      ctx.lineTo(-10, -7);
      ctx.lineTo(-10, 7);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    // fuel bar
    ctx.fillStyle = 'red';
    ctx.fillRect(10, 10, (ship.fuel / CONFIG.ship.maxFuel) * 100, 8);
    ctx.strokeStyle = 'black';
    ctx.strokeRect(10, 10, 100, 8);
    if (!ship.alive) {
      ctx.fillStyle = 'white';
      ctx.font = '30px sans-serif';
      ctx.fillText('Game Over', CONFIG.width / 2 - 80, CONFIG.height / 2);
    }
  }

input.newString:
// Pre‑generated starfield for background
const stars = [];
for (let i = 0; i < 150; i++) {
  stars.push({
    x: Math.random() * CONFIG.width,
    y: Math.random() * CONFIG.height,
    radius: Math.random() * 1.5 + 0.5,
    alpha: Math.random() * 0.5 + 0.3,
  });
}

// Thrust particle pool
const particles = [];
function spawnParticle() {
  particles.push({
    x: ship.x,
    y: ship.y,
    vx: -Math.cos(ship.angle) * (Math.random() * 0.5 + 0.5) - ship.vx * 0.2,
    vy: -Math.sin(ship.angle) * (Math.random() * 0.5 + 0.5) - ship.vy * 0.2,
    life: 30 + Math.random() * 20,
  });
}

function draw() {
    ctx.clearRect(0, 0, CONFIG.width, CONFIG.height);
    // Starfield
    ctx.fillStyle = 'white';
    for (const s of stars) {
      ctx.globalAlpha = s.alpha;
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    // rotating planet with gradient
    ctx.save();
    ctx.translate(CONFIG.width / 2, CONFIG.height / 2);
    ctx.rotate(bgAngle);
    const grad = ctx.createRadialGradient(0, 0, 80, 0, 0, 200);
    grad.addColorStop(0, '#445');
    grad.addColorStop(1, '#001');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(0, 0, 200, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    // draw orbs with glow
    for (const o of orbs) {
      if (o.collected) continue;
      const glow = ctx.createRadialGradient(o.x, o.y, 0, o.x, o.y, CONFIG.orb.radius * 4);
      glow.addColorStop(0, 'rgba(255,255,0,0.8)');
      glow.addColorStop(1, 'rgba(255,255,0,0)');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(o.x, o.y, CONFIG.orb.radius * 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = 'yellow';
      ctx.beginPath();
      ctx.arc(o.x, o.y, CONFIG.orb.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // draw asteroids with simple shading
    for (const a of asteroids) {
      const aGrad = ctx.createRadialGradient(a.x, a.y, 0, a.x, a.y, CONFIG.asteroid.radius);
      aGrad.addColorStop(0, '#aaa');
      aGrad.addColorStop(1, '#555');
      ctx.fillStyle = aGrad;
      ctx.beginPath();
      ctx.arc(a.x, a.y, CONFIG.asteroid.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // draw thrust particles
    ctx.fillStyle = 'orange';
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life--;
      if (p.life <= 0) { particles.splice(i, 1); continue; }
      ctx.globalAlpha = p.life / 50;
      ctx.beginPath();
      ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    // draw ship with crisp shape
    if (ship.alive) {
      ctx.save();
      ctx.translate(ship.x, ship.y);
      ctx.rotate(ship.angle);
      ctx.fillStyle = 'white';
      ctx.strokeStyle = '#0ff';
      ctx.lineWidth = 0.5;
      ctx.beginPath();
      ctx.moveTo(12, 0);
      ctx.lineTo(-8, -7);
      ctx.lineTo(-8, 7);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
      ctx.restore();
    }
    // fuel bar
    ctx.fillStyle = 'red';
    ctx.fillRect(10, 10, (ship.fuel / CONFIG.ship.maxFuel) * 100, 8);
    ctx.strokeStyle = 'black';
    ctx.strokeRect(10, 10, 100, 8);
    if (!ship.alive) {
      ctx.fillStyle = 'white';
      ctx.font = '30px sans-serif';
      ctx.fillText('Game Over', CONFIG.width / 2 - 80, CONFIG.height / 2);
    }
  }

